"""Used by CMake to embed the rocFFT JIT callback SPIR-V module as a C++ array."""

import sys
from pathlib import Path


BYTES_PER_LINE = 16


def write_rocfft_callbacks(spirv_filename: str, output_filename: str) -> None:
    blob = Path(spirv_filename).read_bytes()
    lines = [
        "// @generated by scripts/write_rocfft_callbacks.py\n",
        "\n",
        "#pragma once\n",
        "\n",
        "#include <cstddef>\n",
        "#include <cstdint>\n",
        "\n",
        "namespace at::native::detail {\n",
        "\n",
        "// SPIR-V is a stream of 32-bit words, so keep the blob word aligned.\n",
        "alignas(4) inline constexpr uint8_t kRocFFTCallbackSPIRV[] = {\n",
    ]
    for start in range(0, len(blob), BYTES_PER_LINE):
        chunk = blob[start : start + BYTES_PER_LINE]
        lines.append("    " + "".join(f"0x{byte:02x}," for byte in chunk) + "\n")
    lines += [
        "};\n",
        "\n",
        "inline constexpr size_t kRocFFTCallbackSPIRVSize = sizeof(kRocFFTCallbackSPIRV);\n",
        "\n",
        "} // namespace at::native::detail\n",
    ]

    with open(output_filename, "w") as out:
        out.writelines(lines)


if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(f"Usage:\n {sys.argv[0]} spirv_filename output_filename")
        sys.exit(1)

    write_rocfft_callbacks(sys.argv[1], sys.argv[2])
